#include <assimp/Importer.hpp>
#include <assimp/scene.h>
#include <assimp/version.h>
#include <iomanip>
#include <iostream>
#include <string>

static void quoted(const std::string& s) {
    std::cout << '"';
    for (unsigned char c : s) {
        if (c == '"' || c == '\\') std::cout << '\\' << c;
        else if (c < 32) std::cout << "\\u00" << std::hex << std::setw(2)
                                  << std::setfill('0') << unsigned(c) << std::dec;
        else std::cout << c;
    }
    std::cout << '"';
}

static void nodes(const aiScene* scene, const aiNode* node,
                  const aiMatrix4x4& parent, bool& first) {
    const aiMatrix4x4 transform = parent * node->mTransformation;
    for (unsigned i = 0; i < node->mNumMeshes; ++i) {
        const auto* mesh = scene->mMeshes[node->mMeshes[i]];
        if (!first) std::cout << ',';
        first = false;
        std::cout << "{\"name\":"; quoted(mesh->mName.C_Str());
        std::cout << ",\"faces\":" << mesh->mNumFaces << ",\"vertices\":[";
        for (unsigned j = 0; j < mesh->mNumVertices; ++j) {
            if (j) std::cout << ',';
            const auto v = transform * mesh->mVertices[j];
            std::cout << '[' << v.x << ',' << v.y << ',' << v.z << ']';
        }
        std::cout << "]}";
    }
    for (unsigned i = 0; i < node->mNumChildren; ++i)
        nodes(scene, node->mChildren[i], transform, first);
}

int main(int argc, char** argv) {
    if (argc != 2) return 2;
    Assimp::Importer importer;
    const auto* scene = importer.ReadFile(argv[1], 0); // no postprocessing
    std::cout << std::setprecision(9) << "{\"runtime\":\""
              << aiGetVersionMajor() << '.' << aiGetVersionMinor() << '.'
              << aiGetVersionPatch() << "\",\"revision\":" << aiGetVersionRevision()
              << ",\"success\":" << (scene ? "true" : "false") << ",\"error\":";
    quoted(importer.GetErrorString());
    std::cout << ",\"meshes\":[";
    bool first = true;
    if (scene && scene->mRootNode) nodes(scene, scene->mRootNode, aiMatrix4x4{}, first);
    std::cout << "]}\n";
    return 0; // observation, not support admission
}
